      }
      if (value < 0) {
        throw ConfigException('"jobs.$key" must be >= 0 (0 disables)');
      }
      return value;
    }

    final maxLogBytesValue = node['maxLogBytes'];
    if (maxLogBytesValue != null) {
      if (maxLogBytesValue is! int) {
        throw ConfigException('"jobs.maxLogBytes" must be an integer');
      }
